<h1><?= te('Background and drug screening') ?></h1><p class="sub"><?= te('Authorization, provider coordination and clearance tracking. Detailed medical and background reports stay with the authorized provider.') ?></p><?php if(!$own): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="issue"><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><div class="row"><div><label><?= te('Screening') ?></label><select name="kind"><option value="background"><?= te('Background check') ?></option><option value="drug"><?= te('Drug screen') ?></option></select></div><div><label><?= te('Delivery') ?></label><select name="delivery_mode"><option value="agency"><?= te('Screening agency') ?></option><option value="mobile_bus"><?= te('Mobile screening bus') ?></option><option value="onsite"><?= te('On site') ?></option></select></div></div><label><?= te('Provider') ?></label><input name="provider_name" maxlength="190"><label><?= te('Location') ?></label><input name="location" maxlength="255"><label><?= te('Instructions / appointment details') ?></label><textarea name="instructions"></textarea><label><?= te('Who pays') ?></label><select name="payer"><option value="agency"><?= te('Agency') ?></option><option value="client"><?= te('Client') ?></option><option value="worker_reimbursement"><?= te('Worker pays, reimbursement against receipt') ?></option></select><label><?= te('Approved authorization text to sign') ?></label><textarea name="authorization_text" required></textarea><button class="btn"><?= te('Issue authorization') ?></button></form><?php endif; ?><?php foreach($cases as $s): ?><div class="card"><h2><?= e(($s['full_name'] ?? '').' · '.$s['kind'].' · '.$s['project']) ?></h2><p><?= e($s['status'].' · consent '.$s['consent'].' · '.$s['delivery_mode'].' · '.$s['provider_name']) ?></p><p><?= e($s['location'].' · '.$s['instructions'].' · payer '.$s['payer']) ?></p><?php if($own): ?><a href="/agreements"><?= te('Open authorization') ?></a><?php else: ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="status"><input type="hidden" name="case_id" value="<?= (int)$s['id'] ?>"><select name="status"><?php foreach(['scheduled','completed','cleared','not_cleared','cancelled'] as $x): ?><option><?= e($x) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Review / update') ?></button></form><?php endif; ?></div><?php endforeach; ?>